/* From Uiverse.io by javierBarroso - Source: EmmaxPlay - Tags: card, radio, creative, cool card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  margin: 0 auto;
  background-color: #f4f4f3;
  border-radius: 8px;
  z-index: 1;
  position: relative;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .card::after {
  position: absolute;
  content: '';
  background-color: #454a50;
  width: 50px;
  height: 100px;
  z-index: -1;
  border-radius: 8px;
}

.__UIV_SCOPE__ .tools {
  display: flex;
  align-items: center;
  padding: 9px;
  border-radius: 8px;
  background: #454a50;
  margin-top: -2px;
}

.__UIV_SCOPE__ .circle {
  padding: 0 4px;
}

.__UIV_SCOPE__ .card__content {
  height: 100%;
  margin: 0px;
  border-radius: 8px;
  background: #f4f4f3;
  padding: 10px;
}

.__UIV_SCOPE__ .title {
  font-size: 20px;
}

.__UIV_SCOPE__ .content {
  margin-top: 10px;
  font-size: 14px;
}

.__UIV_SCOPE__ .box {
  display: inline-block;
  align-items: center;
  width: 10px;
  height: 10px;
  padding: 1px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .red {
  background-color: #ff605c;
}

.__UIV_SCOPE__ .yellow {
  background-color: #ffbd44;
}

.__UIV_SCOPE__ .green {
  background-color: #00ca4e;
}
